using Microsoft.AspNetCore.Mvc; using TuneHire.Api.Data; using TuneHire.Api.Models; namespace TuneHire.Api.Controllers { [ApiController] [Route("api/[controller]")] public class ReviewsController : ControllerBase { private readonly AppDbContext _db; public ReviewsController(AppDbContext db) { _db = db; } [HttpPost] public IActionResult Create(Review r) { _db.Reviews.Add(r); _db.SaveChanges(); return CreatedAtAction(nameof(GetById), new { id = r.Id }, r); } [HttpGet("musician/{musicianId}")] public IActionResult ForMusician(int musicianId) { var reviews = from rv in _db.Reviews join bk in _db.Bookings on rv.BookingId equals bk.Id where bk.MusicianId == musicianId select rv; return Ok(reviews.ToList()); } [HttpGet("{id}")] public IActionResult GetById(int id) => Ok(_db.Reviews.Find(id)); } }